const resultados={primeiro:{data:'4 de outubro de 2026',validos:'125.272.513',brancos:'2.300.781',brancosPct:'1,84%',nulos:'3.674.149',nulosPct:'2,93%',candidatos:[{nome:'Flávio Bolsonaro',partido:'PL',votos:'56.104.268',pct:'47,03%',status:'1º lugar'},{nome:'Luiz Inácio Lula da Silva',partido:'PT',votos:'53.876.617',pct:'45,16%',status:'2º lugar'}]},segundo:{data:'25 de outubro de 2026',validos:'124.082.273',brancos:'1.430.496',brancosPct:'1,12%',nulos:'2.723.305',nulosPct:'2,12%',candidatos:[{nome:'Luiz Inácio Lula da Silva',partido:'PT',votos:'64.256.232',pct:'51,79%',status:'Reeleito · 1º lugar'},{nome:'Flávio Bolsonaro',partido:'PL',votos:'59.826.041',pct:'48,21%',status:'2º lugar'}]}};
const fonte='https://resultados.tse.jus.br';
function turno(titulo,d){return `<article class="resultado-turno"><header><span>${titulo}</span><small>${d.data}</small></header><div class="resultado-candidatos">${d.candidatos.map(c=>`<div><b>${c.status}</b><h5>${c.nome} <small>${c.partido}</small></h5><strong>${c.pct}</strong><p>${c.votos} votos</p></div>`).join('')}</div><footer><span><b>${d.validos}</b> votos válidos</span><span><b>${d.brancos}</b> brancos · ${d.brancosPct}</span><span><b>${d.nulos}</b> nulos · ${d.nulosPct}</span></footer></article>`}
function aplicar(){const raiz=document.querySelector('.eleicoes-2026');if(!raiz||raiz.querySelector('.resultado-eleicao-2026'))return;const alvo=raiz.querySelector('.eleicao-pacotes')||raiz.querySelector('.eleicao-lista');if(!alvo)return;const s=document.createElement('section');s.className='resultado-eleicao-2026';s.innerHTML=`<div class="resultado-titulo"><span class="rotulo">RESULTADO OFICIAL · PRESIDÊNCIA DA REPÚBLICA</span><h4>Luiz Inácio Lula da Silva é reeleito presidente da República.</h4><p class="resultado-marco">Eleito pelo voto popular para a Presidência pela quarta vez, Lula venceu sua segunda eleição presidencial consecutiva, após as vitórias de 2002, 2006, 2022 e 2026. No segundo turno de 25 de outubro, recebeu 64.256.232 votos, equivalentes a 51,79% dos votos válidos.</p><p>Votação nacional. Percentuais dos candidatos calculados sobre os votos válidos.</p></div>${turno('1º TURNO',resultados.primeiro)}${turno('2º TURNO',resultados.segundo)}<a class="resultado-fonte" href="${fonte}" target="_blank" rel="noopener noreferrer">Fonte oficial: Tribunal Superior Eleitoral ↗</a>`;alvo.before(s)}
const css=document.createElement('style');css.textContent=`.resultado-eleicao-2026{margin:28px 0;padding:24px;border:1px solid rgba(197,164,96,.28);background:rgba(7,13,12,.72)}.resultado-titulo h4{font-size:clamp(1.5rem,3vw,2.35rem);margin:.35rem 0}.resultado-titulo p{opacity:.72}.resultado-titulo .resultado-marco{max-width:900px;font-size:clamp(.98rem,1.7vw,1.12rem);line-height:1.65;opacity:.9;border-left:2px solid rgba(197,164,96,.6);padding-left:14px}.resultado-turno{margin-top:20px;border-top:1px solid rgba(255,255,255,.12);padding-top:18px}.resultado-turno>header{display:flex;justify-content:space-between;gap:16px;align-items:end}.resultado-turno>header span{font-weight:800;letter-spacing:.12em}.resultado-turno>header small{opacity:.65}.resultado-candidatos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}.resultado-candidatos>div{padding:18px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.025)}.resultado-candidatos b{font-size:.72rem;letter-spacing:.08em;opacity:.7}.resultado-candidatos h5{font-size:1.05rem;margin:8px 0}.resultado-candidatos h5 small{font-size:.72rem;opacity:.62}.resultado-candidatos strong{display:block;font-size:clamp(1.7rem,4vw,2.7rem);font-family:serif}.resultado-candidatos p{margin:.2rem 0 0;opacity:.72}.resultado-turno footer{display:flex;flex-wrap:wrap;gap:8px 18px;font-size:.86rem;opacity:.78}.resultado-fonte{display:inline-block;margin-top:20px;text-decoration:underline;text-underline-offset:4px}@media(max-width:650px){.resultado-eleicao-2026{padding:18px 14px}.resultado-candidatos{grid-template-columns:1fr}.resultado-turno>header{align-items:start;flex-direction:column;gap:4px}}`;document.head.append(css);
new MutationObserver(aplicar).observe(document.body,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest?.('[data-obs-aba="eleicoes2026"]'))setTimeout(aplicar,120)});aplicar();